function validate([sentence, k]) {
  if (typeof sentence !== 'string' || sentence.length < 1 || sentence.length > 5000) return 'sentence needs 1 to 5000 characters.';
  if (!/^[a-z]+( [a-z]+)*$/.test(sentence)) return 'sentence is lowercase words separated by single spaces.';
  if (!Number.isInteger(k) || k < 1 || k > 5000) return 'k is between 1 and 5000.';
  if (sentence.split(' ').some(word => word.length > k)) return 'Every word must fit in k characters.';
  return null;
}

