function minimumCost(sentence, k) {
  const words = sentence.split(' ');
  const count = words.length;
  const dp = new Array(count).fill(Infinity);

  for (let start = count - 1; start >= 0; start--) {
    let length = -1;
    for (let end = start; end < count; end++) {
      length += words[end].length + 1;
      if (length > k) {
        break;
      }
      if (end === count - 1) {
        dp[start] = 0;
      } else {
        const cost = (k - length) ** 2;
        dp[start] = Math.min(dp[start], cost + dp[end + 1]);
      }
    }
  }
  return dp[0];
}

