function minimumCost(sentence, k) {
  const words = sentence.split(' ');
  const gaps = words.length - 1;
  let best = Infinity;
  // Each bit of mask says whether a row break goes after that word.
  for (let mask = 0; mask < 1 << gaps; mask++) {
    const rows = [];
    let row = words[0];
    for (let g = 0; g < gaps; g++) {
      if (mask & (1 << g)) { rows.push(row); row = words[g + 1]; }
      else row += ' ' + words[g + 1];
    }
    rows.push(row);
    if (rows.some(r => r.length > k)) continue;
    let total = 0;
    for (let r = 0; r + 1 < rows.length; r++) total += (k - rows[r].length) * (k - rows[r].length);
    best = Math.min(best, total);
  }
  return best;
}

