function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const maxWord = size === 'large' ? 1 + Math.floor(rand() * 12) : 1 + Math.floor(rand() * 5);
  const wordCount = size === 'large' ? 300 + Math.floor(rand() * 500) : 1 + Math.floor(rand() * 8);
  const words = [];
  let longest = 0;
  let total = -1;
  for (let w = 0; w < wordCount; w++) {
    const len = 1 + Math.floor(rand() * maxWord);
    if (total + len + 1 > 5000) break;
    let word = '';
    for (let c = 0; c < len; c++) word += letters[Math.floor(rand() * (size === 'large' ? 26 : 3))];
    words.push(word);
    total += len + 1;
    longest = Math.max(longest, len);
  }
  const slack = size === 'large' ? Math.floor(rand() * 60) : Math.floor(rand() * 10);
  return [words.join(' '), longest + slack];
}
